<script setup>
import {ref,computed,onMounted} from 'vue'
import {api,number} from './api.mjs'
const props=defineProps({boot:Object,locked:Boolean}),emit=defineEmits(['refresh','submit'])
const draft=ref(null),parent=ref(''),error=ref(''),working=ref(false),group=ref('land'),saved=ref('')
const revisions=computed(()=>props.boot.schemes.filter(s=>s.payload?.modelFamily==='grid-continuous-v1'))
const groups=computed(()=>[...new Set(props.boot.parameterDefinitions.map(d=>d.group))])
const labels={land:'陆面产流',snow:'冰雪过程',routing:'分水源与河道汇流',lake:'湖泊'}
const definitions=computed(()=>props.boot.parameterDefinitions.filter(d=>d.group===group.value))
const initial=k=>draft.value.search.scope==='duja'&&k!=='lakeCoefficient'?draft.value.partitionParameters.duja?.[k]??draft.value.parameters[k]:draft.value.parameters[k]
function change(k,v){if(draft.value.search.scope==='duja'&&k!=='lakeCoefficient')draft.value.partitionParameters.duja={...draft.value.partitionParameters.duja,[k]:v};else draft.value.parameters[k]=v;saved.value=''}
async function create(){try{draft.value=await api('research-template');parent.value='';saved.value='';error.value=''}catch(e){error.value=e.message}}
function select(id){if(!id){create();return}const row=revisions.value.find(s=>s.id===id);draft.value=JSON.parse(JSON.stringify(row.payload));parent.value=id;saved.value=''}
function copy(){parent.value='';draft.value.name+=' · 副本';saved.value=''}
function target(){draft.value.search.keys=draft.value.target==='lake'?['lakeCoefficient']:['KC','WM','B','SM','KI','KG','tauHours','interflowTauHours','baseflowTauHours'];if(draft.value.target==='lake')draft.value.search.scope='background'}
async function save(kind){working.value=true;error.value='';try{const row=await api('schemes',{payload:draft.value,parentId:parent.value||undefined});parent.value=row.id;saved.value='已保存修订 '+row.payload.revision+' · '+row.payload.configurationSHA256.slice(0,12);emit('refresh');if(kind)emit('submit',{kind,researchSchemeId:row.id,name:draft.value.name+(kind==='calibration'?' · 参数率定':' · 连续模拟')})}catch(e){error.value=e.message}finally{working.value=false}}
onMounted(create)
</script>
<template><div class="research-schemes"><div class="result-toolbar"><label class="grow">我的方案修订<select :value="parent" @change="select($event.target.value)"><option value="">新建：标准参数工作副本</option><option v-for="s in revisions" :key="s.id" :value="s.id">{{s.name}} · 修订 {{s.payload.revision}}</option></select></label><button @click="create">新建方案</button><button :disabled="!draft" @click="copy">复制方案</button></div><p v-if="error" class="message error" role="alert">{{error}}</p><p v-if="saved" class="message success">{{saved}}</p>
<template v-if="draft"><div class="query-grid"><label class="grow">方案名称<input v-model="draft.name" maxlength="120"></label><label>率定对象<select v-model="draft.target" @change="target"><option value="duja">杜加产汇流参数</option><option value="lake">主站连续湖位 · 蒸发系数</option></select></label><label>参数区域<select v-model="draft.search.scope" :disabled="draft.target==='lake'"><option value="duja">杜加控制区</option><option value="background">未单独配置的背景分区</option></select></label></div>
<div class="research-context"><b>逐格网连续模拟 · 候选方案</b><span>0.1°格网 × 排水分区 × 500米垂直高程带 × 冰川/陆面</span><span v-if="boot.gridSpatial">{{boot.gridSpatial.drainage?.unresolvedAreaKm2.toFixed(1)}} km²排水归属未核实，独立保留产流，不进入已核实入湖合计</span></div>
<fieldset class="research-periods"><legend>资料与时段（北京时间，止日不含当日）</legend><label class="grow">冻结气象输入<select v-model="draft.inputId"><option v-for="i in boot.inputs" :key="i.id" :value="i.id">{{i.name}} · {{i.manifest.start.slice(0,10)}}—{{i.manifest.end.slice(0,10)}}</option></select></label><label v-for="(label,key) in {warmupStart:'预热起日',trainingStart:'训练起日',trainingEnd:'训练止日',evaluationStart:'评价起日',evaluationEnd:'评价止日'}" :key="key">{{label}}<input type="date" :value="draft.periods[key].slice(0,10)" @input="draft.periods[key]=$event.target.value+'T00:00:00'"></label></fieldset>
<div class="result-toolbar"><label v-for="(label,key) in {runoff:'产流阶段预算',routing:'汇流阶段预算',lake:'湖泊阶段预算'}" :key="key">{{label}}<input type="number" v-model.number="draft.search.budgets[key]" min="1" max="2000"></label><label>随机种子<input type="number" v-model.number="draft.search.seed" min="0" max="4294967295"></label><label>流量目标<select v-model="draft.search.objectiveProfile"><option value="balanced">综合误差</option><option value="peaks">偏重洪峰</option></select></label></div><p class="muted">训练期用于搜索、排序和停止判断；评价期仅在选定参数后计算。湖泊对象使用主站连续湖位RMSE。高级研究参数缺少独立过程观测，需检查过拟合和触边。</p>
<div class="parameter-group-tabs"><button v-for="g in groups" :key="g" :class="{primary:g===group}" @click="group=g">{{labels[g]||g}}</button></div><div class="table-wrap research-parameters"><table><thead><tr><th>参与搜索</th><th>参数 / 单位</th><th>初始值</th><th>搜索下界</th><th>搜索上界</th><th>物理范围</th></tr></thead><tbody><tr v-for="d in definitions" :key="d.key"><td><input type="checkbox" v-model="draft.search.keys" :value="d.key" :disabled="draft.target==='lake'?d.key!=='lakeCoefficient':d.key==='lakeCoefficient'" :aria-label="'搜索'+d.label"></td><td :title="d.parameterBasis">{{d.label}}<small>{{d.unit||'无量纲'}}</small></td><td><input type="number" :step="d.step" :value="initial(d.key)" :aria-label="d.label+'初始值'" @input="change(d.key,Number($event.target.value))"></td><td><input type="number" v-model.number="draft.search.bounds[d.key][0]" :step="d.step" :aria-label="d.label+'下界'"></td><td><input type="number" v-model.number="draft.search.bounds[d.key][1]" :step="d.step" :aria-label="d.label+'上界'"></td><td>{{number(d.min,5)}}—{{number(d.max,5)}}</td></tr></tbody></table></div>
<details><summary>初始化与空间版本</summary><p>陆面从预热起点连续计算。湖位取首个可靠主站日值作为午间锚点，停测、跨年和新增观测均不重置。四岸订正候选不进入率定。</p><dl><dt>空间版本</dt><dd>{{draft.spatialVersion}}</dd><dt>湖泊</dt><dd>定面积水量平衡；锚点前仅相对水量</dd></dl></details><div class="actions research-actions"><button :disabled="working||locked" @click="save()">保存新修订</button><button :disabled="working||locked" @click="save('simulation')">保存并运行原参数基线</button><button class="primary" :disabled="working||locked" @click="save('calibration')">保存并开始率定</button></div></template></div></template>
<style scoped>.research-context{display:grid;gap:8px;background:var(--bg);border-left:3px solid var(--accent);padding:16px;margin:20px 0;font-size:13px}.research-periods{display:flex;gap:16px;flex-wrap:wrap;border:1px solid var(--line);padding:18px;margin:20px 0}.research-periods legend{font-size:14px}.research-periods label{min-width:130px;flex:1}.research-periods .grow{flex-basis:100%}.research-parameters table{min-width:820px}.research-parameters input[type=number]{width:100%;min-width:90px}.research-parameters td small{display:block;color:var(--muted);font-size:12px}.research-actions{margin-top:24px;justify-content:flex-end}.research-schemes{min-width:0}</style>
